local HostBuilder = require(script.Parent.HostBuilder)

return function()
	describe("AddAppConfigurationFolder", function()
		beforeEach(function()
			local FacadeFactory = require(script.Parent.FacadeFactory)
			FacadeFactory.__innerDispose()
		end)

		afterEach(function() end)

		it("should create new instance successfully", function()
			local builder = HostBuilder.new()
			builder:ConfigureAppConfigurationFolder(game.ReplicatedStorage.Configs.SystemConfigs)

			expect(builder).to.be.ok()
			local host = builder:Build()
			local configuration = host.Services:GetService("IConfiguration")
			expect(configuration).to.be.ok()
			expect(configuration.ComponentAConfig.Killed).to.equal(2)
		end)
	end)
end
